    @Test
    public void testIsSameLocalTime_IdenticalCalendars() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        // Ensure they are exactly the same by using the same instance or same values
        Assert.assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_SameValuesDifferentInstances() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(2023, Calendar.OCTOBER, 10, 14, 30, 45);
        cal1.set(Calendar.MILLISECOND, 500);

        cal2.set(2023, Calendar.OCTOBER, 10, 14, 30, 45);
        cal2.set(Calendar.MILLISECOND, 500);

        Assert.assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentYear() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal1.set(2023, Calendar.JANUARY, 1, 12, 0, 0);
        cal2.set(2024, Calendar.JANUARY, 1, 12, 0, 0);
        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentEra() {
        Calendar cal1 = new GregorianCalendar(Calendar.GREGORIAN, Calendar.BC, 1, 1, 1, 1, 1);
        Calendar cal2 = new GregorianCalendar(Calendar.GREGORIAN, Calendar.AD, 1, 1, 1, 1, 1);
        // Note: ERA check is part of the logic
        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

